-- Plan highlights describe only what ships today. Rows edited by a Super Admin are left alone.
UPDATE plans SET highlights = '["Up to 20 employees", "1 branch", "Web & mobile attendance", "Leave management", "Employee self-service", "On-screen reports"]'::jsonb WHERE code = 'BASIC' AND highlights = '["Up to 20 employees", "1 branch", "Attendance & leave", "Employee self-service", "Basic reports"]'::jsonb;
UPDATE plans SET highlights = '["Up to 50 employees", "2 branches", "Nepal payroll (tax, SSF, PF, CIT)", "Biometric devices", "Shift schedules", "PDF/Excel export & document alerts"]'::jsonb WHERE code = 'PROFESSIONAL' AND highlights = '["Up to 50 employees", "2 branches", "Payroll", "Shift scheduling", "Recruitment", "Custom approval workflows"]'::jsonb;
UPDATE plans SET highlights = '["Up to 150 employees", "5 branches", "50 GB document storage", "Everything in Professional", "Upcoming modules included as they launch"]'::jsonb WHERE code = 'BUSINESS' AND highlights = '["Up to 150 employees", "5 branches", "Advanced payroll", "KPI & appraisal", "Advanced analytics", "API integrations"]'::jsonb;
UPDATE plans SET highlights = '["150+ employees", "Negotiated limits and price", "Features enabled to your needs", "Dedicated deployment on request", "Dedicated onboarding"]'::jsonb WHERE code = 'ENTERPRISE' AND highlights = '["150+ employees", "Custom capacity", "Dedicated deployment option", "Custom integrations", "Dedicated account manager"]'::jsonb;
